#!/usr/bin/env bash
#
# gosite infra <up|down|status|logs>
#
# Manages the shared infrastructure (Postgres + Redis) that every project on
# the machine attaches to through the external '${GOSITE_NETWORK}' network.
#

_infra_write_compose() {
  mkdir -p "${GOSITE_INFRA_DIR}"
  cat > "${GOSITE_INFRA_DIR}/docker-compose.yml" <<EOF
# Generated by gosite. Shared local infrastructure for every project.
services:
  postgres:
    image: postgres:16-alpine
    container_name: ${GOSITE_PG_HOST}
    restart: unless-stopped
    environment:
      POSTGRES_USER: ${GOSITE_PG_USER}
      POSTGRES_PASSWORD: ${GOSITE_PG_PASSWORD}
      POSTGRES_DB: postgres
    ports:
      - "${GOSITE_PG_PORT}:5432"
    volumes:
      - gosite-pgdata:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U ${GOSITE_PG_USER}"]
      interval: 10s
      timeout: 5s
      retries: 5
    networks: [gosite]

  redis:
    image: redis:7-alpine
    container_name: ${GOSITE_REDIS_HOST}
    restart: unless-stopped
    command: ["redis-server", "--appendonly", "yes", "--maxmemory-policy", "allkeys-lru"]
    ports:
      - "${GOSITE_REDIS_PORT}:6379"
    volumes:
      - gosite-redisdata:/data
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 10s
      timeout: 5s
      retries: 5
    networks: [gosite]

volumes:
  gosite-pgdata:
  gosite-redisdata:

networks:
  gosite:
    external: true
    name: ${GOSITE_NETWORK}
EOF
}

_infra_compose() {
  compose -p "${GOSITE_INFRA_PROJECT}" -f "${GOSITE_INFRA_DIR}/docker-compose.yml" "$@"
}

cmd_infra() {
  local action="${1:-status}"
  [[ $# -gt 0 ]] && shift || true
  require_dependencies

  case "${action}" in
    up)
      ensure_network
      _infra_write_compose
      info "Starting shared infrastructure (${GOSITE_PG_HOST}, ${GOSITE_REDIS_HOST})"
      _infra_compose up -d
      ok "Postgres  -> localhost:${GOSITE_PG_PORT} (user: ${GOSITE_PG_USER})"
      ok "Redis     -> localhost:${GOSITE_REDIS_PORT}"
      printf "${C_DIM}From a project container use the hostnames '%s' and '%s'.${C_NC}\n" \
        "${GOSITE_PG_HOST}" "${GOSITE_REDIS_HOST}"
      ;;
    down)
      [[ -f "${GOSITE_INFRA_DIR}/docker-compose.yml" ]] || fatal "Infrastructure was never created. Run 'gosite infra up'."
      info "Stopping shared infrastructure"
      _infra_compose down
      ok "Infrastructure stopped (data volumes preserved)."
      ;;
    status)
      if network_exists "${GOSITE_NETWORK}"; then
        ok "Network '${GOSITE_NETWORK}' exists."
      else
        warn "Network '${GOSITE_NETWORK}' is missing. Run 'gosite infra up'."
      fi
      local svc
      for svc in "${GOSITE_PG_HOST}" "${GOSITE_REDIS_HOST}"; do
        if container_running "${svc}"; then
          ok "${svc}: running"
        elif container_exists "${svc}"; then
          warn "${svc}: stopped"
        else
          err "${svc}: not created"
        fi
      done
      ;;
    logs)
      [[ -f "${GOSITE_INFRA_DIR}/docker-compose.yml" ]] || fatal "Infrastructure was never created."
      _infra_compose logs -f --tail=100 "$@"
      ;;
    *)
      fatal "Unknown 'infra' action: ${action} (expected up|down|status|logs)"
      ;;
  esac
}
